// ==========================================================================
// SPRINT 7 — PROFILE & SETTINGS v1
// Solo UI/UX/preferenze locali. Nessuna modifica al modello dati / IndexedDB / algoritmi.
// ==========================================================================

var PREFS_STORAGE_KEY = 'prefs';
var USER_NAME_STORAGE_KEY = 'user.name';
var USER_INSTALLED_KEY = 'user.installedAt';
var USER_NAME_PREFILL_KEY = 'user.namePrefilledAt';
var APP_META = { version: '1.7.0', codename: 'Sprint 7 — Profilo' };

var PREF_DEFS = [
    { key: 'reducedMotion', group: 'Aspetto',       label: 'Riduci animazioni',          type: 'switch',   wired: true,  meta: 'Disattiva transizioni e movimenti non essenziali.' },
    { key: 'textSize',       group: 'Aspetto',      label: 'Dimensione testo',           type: 'segmented', wired: true, options: [ { value: 'sm', label: 'Compatto' }, { value: 'md', label: 'Normale' }, { value: 'lg', label: 'Grande' } ], meta: 'Ridimensiona i testi dell\'interfaccia.' },
    { key: 'weightUnit',     group: 'Workout',      label: 'Unità peso',                 type: 'segmented', wired: true, options: [ { value: 'kg', label: 'kg' }, { value: 'lbs', label: 'lbs' } ], meta: 'Etichetta usata nell\'app. I dati restano invariati.' },
    { key: 'focusDefault',   group: 'Workout',      label: 'Focus Mode di default',      type: 'switch',   wired: false, meta: 'Avvia ogni sessione in modalità Focus.' },
    { key: 'restDefaultSec', group: 'Workout',      label: 'Timer di recupero default',  type: 'chips',    wired: false, options: [30, 45, 60, 75, 90], meta: 'Durata iniziale del timer al termine di ogni serie.' },
    { key: 'vibration',      group: 'Accessibilita', label: 'Vibrazione',                type: 'switch',   wired: false, meta: 'Feedback aptico al completamento di serie e timer.' },
    { key: 'sounds',         group: 'Accessibilita', label: 'Suoni',                     type: 'switch',   wired: false, meta: 'Segnali sonori al completamento di serie e timer.' }
];

function getPref(key) {
    var p = S.prefs || {};
    return p[key];
}
function setPref(key, value) {
    if (!S.prefs) S.prefs = {};
    S.prefs[key] = value;
    try { localStorage.setItem(PREFS_STORAGE_KEY, JSON.stringify(S.prefs)); } catch (_e) {}
    applyPrefs();
}
function findPrefDef(key) {
    for (var i = 0; i < PREF_DEFS.length; i++) if (PREF_DEFS[i].key === key) return PREF_DEFS[i];
    return null;
}
function resetPrefs() {
    S.prefs = { reducedMotion: false, textSize: 'md', weightUnit: 'kg', focusDefault: true, restDefaultSec: 60, vibration: false, sounds: false };
    try { localStorage.removeItem(PREFS_STORAGE_KEY); } catch (_e) {}
    applyPrefs();
}

// ---- USER NAME ----------------------------------------------------------
function getUserName() {
    var stored = String((S.user && S.user.name) || '').trim();
    if (stored) return stored;
    var cfg = (S.sync && S.sync.config) || {};
    if (cfg.owner) return String(cfg.owner).trim();
    return 'Atleta';
}
function getUserNameSource() {
    if (S.user && S.user.name && String(S.user.name).trim()) return 'custom';
    var cfg = (S.sync && S.sync.config) || {};
    if (cfg.owner) return 'github';
    return 'default';
}
function sanitizeUserName(raw) {
    var s = String(raw == null ? '' : raw);
    s = s.replace(/[␀-]/g, '').trim();
    if (s.length > 30) s = s.slice(0, 30);
    return s;
}
function setUserName(raw) {
    var name = sanitizeUserName(raw);
    if (!S.user) S.user = { name: '' };
    S.user.name = name;
    try {
        if (name) localStorage.setItem(USER_NAME_STORAGE_KEY, name);
        else localStorage.removeItem(USER_NAME_STORAGE_KEY);
    } catch (_e) {}
}
function initFirstBootUser() {
    try {
        if (!localStorage.getItem(USER_INSTALLED_KEY)) {
            localStorage.setItem(USER_INSTALLED_KEY, now());
        }
        var stored = String(localStorage.getItem(USER_NAME_STORAGE_KEY) || '').trim();
        var cfg = (S.sync && S.sync.config) || {};
        if (!stored && cfg.owner && !localStorage.getItem(USER_NAME_PREFILL_KEY)) {
            var prefill = sanitizeUserName(cfg.owner);
            if (prefill) {
                localStorage.setItem(USER_NAME_STORAGE_KEY, prefill);
                localStorage.setItem(USER_NAME_PREFILL_KEY, now());
                if (!S.user) S.user = { name: '' };
                S.user.name = prefill;
            }
        }
    } catch (_e) {}
}
function userInstalledDate() {
    try {
        var raw = localStorage.getItem(USER_INSTALLED_KEY);
        if (raw) return new Date(raw);
    } catch (_e) {}
    var s = (S.sessions || []).slice().sort(function (a, b) {
        return String(a.startedAt || a.updatedAt || '').localeCompare(String(b.startedAt || b.updatedAt || ''));
    })[0];
    if (s && (s.startedAt || s.updatedAt)) return new Date(s.startedAt || s.updatedAt);
    return new Date();
}
function daysOfUse() {
    var installed = userInstalledDate();
    if (!installed || isNaN(installed.getTime())) return 1;
    var ms = Date.now() - installed.getTime();
    var d = Math.floor(ms / 86400000) + 1;
    return d < 1 ? 1 : d;
}

// ---- PROFILE STATS (derivate) ------------------------------------------
function profileTotalSets() {
    var done = completedSessions();
    var n = 0;
    for (var i = 0; i < done.length; i++) n += sessionSetsDone(done[i]);
    return n;
}
function profileTotalVolume() {
    var done = completedSessions();
    var n = 0;
    for (var i = 0; i < done.length; i++) n += sessionVolume(done[i]);
    return n;
}
function profilePRCount() {
    var done = completedSessions();
    var n = 0;
    for (var i = 0; i < done.length; i++) n += (newPRsInSession(done[i]) || []).length;
    return n;
}
function profileLastWorkoutDate() {
    var done = completedSessions();
    if (!done.length) return null;
    var last = done.slice().sort(function (a, b) {
        return String(b.endedAt || b.updatedAt || '').localeCompare(String(a.endedAt || a.updatedAt || ''));
    })[0];
    return (last && (last.endedAt || last.updatedAt)) ? new Date(last.endedAt || last.updatedAt) : null;
}
function profileLastWorkoutLabel() {
    var d = profileLastWorkoutDate();
    if (!d || isNaN(d.getTime())) return 'Nessun allenamento';
    var ms = Date.now() - d.getTime();
    var days = Math.floor(ms / 86400000);
    if (days <= 0) return 'Oggi';
    if (days === 1) return 'Ieri';
    if (days < 7) return days + ' giorni fa';
    if (days < 30) return Math.floor(days / 7) + ' settimane fa';
    return d.toLocaleDateString('it-IT', { day: '2-digit', month: 'short' });
}

// ---- WEIGHT UNIT (label-only) -------------------------------------------
function weightUnitLabel() { return (S.prefs && S.prefs.weightUnit === 'lbs') ? 'lbs' : 'kg'; }

// ---- RENDERERS ----------------------------------------------------------
function profileHeroHtml() {
    var UI = window.UI;
    var name = getUserName();
    var source = getUserNameSource();
    var initials = initialsOf(name) || 'AT';
    var days = daysOfUse();
    var workouts = completedSessions().length;
    var lastLabel = profileLastWorkoutLabel();
    var editBtn = UI.Button
        ? UI.Button({ label: 'Modifica nome', variant: 'ghost', dataset: { action: 'profile-edit-name' } })
        : '<button type="button" class="c-btn c-btn--ghost" data-action="profile-edit-name">Modifica nome</button>';
    var srcHint = source === 'github' ? '<span class="profileHero__hint">via GitHub</span>' : (source === 'default' ? '<span class="profileHero__hint">Tocca per personalizzare</span>' : '');
    return '<section class="profileV2__hero" role="region" aria-label="Profilo utente">' +
        '<div class="profileHero__row">' +
            '<div class="profileHero__avatar" aria-hidden="true" data-src="' + esc(source) + '">' + esc(initials) + '</div>' +
            '<div class="profileHero__body">' +
                '<h2 class="profileHero__name">' + esc(name) + '</h2>' +
                '<p class="profileHero__meta">' + fmtNum(workouts) + ' workout · ' + fmtNum(days) + ' ' + (days === 1 ? 'giorno' : 'giorni') + ' con l\'app</p>' +
                srcHint +
            '</div>' +
            '<div class="profileHero__cta">' + editBtn + '</div>' +
        '</div>' +
        '<div class="profileHero__kpis">' +
            '<div class="profileHero__kpi"><span class="profileHero__kpiValue">' + fmtNum(workouts) + '</span><span class="profileHero__kpiLabel">Workout</span></div>' +
            '<div class="profileHero__kpi"><span class="profileHero__kpiValue">' + fmtNum(days) + '</span><span class="profileHero__kpiLabel">' + (days === 1 ? 'Giorno' : 'Giorni') + '</span></div>' +
            '<div class="profileHero__kpi"><span class="profileHero__kpiValue">' + esc(lastLabel) + '</span><span class="profileHero__kpiLabel">Ultimo</span></div>' +
        '</div>' +
    '</section>';
}
function profileQuickActionsHtml() {
    var items = [];
    items.push({ icon: 'palette',  label: 'Tema',     action: 'profile-cycle-theme' });
    items.push({ icon: 'user',     label: 'Nome',     action: 'profile-edit-name' });
    items.push({ icon: 'download', label: 'Esporta',  action: 'export-all' });
    items.push({ icon: 'upload',   label: 'Importa',  action: 'import-json' });
    if (S.active) {
        items.push({ icon: 'play',    label: 'Continua sessione', action: 'session-continue', primary: true });
        items.push({ icon: 'trash',   label: 'Elimina sessione',  action: 'session-discard',  danger: true });
    }
    var buttons = items.map(function (it) {
        var cls = 'profileQuick__btn' + (it.primary ? ' is-primary' : '') + (it.danger ? ' is-danger' : '');
        return '<button type="button" class="' + cls + '" data-action="' + esc(it.action) + '" aria-label="' + esc(it.label) + '">' +
            '<span class="profileQuick__icon" aria-hidden="true">' + esc(quickActionIcon(it.icon)) + '</span>' +
            '<span class="profileQuick__label">' + esc(it.label) + '</span>' +
        '</button>';
    }).join('');
    return '<section class="profileV2__section profileV2__quick" role="region" aria-label="Azioni rapide">' +
        '<div class="profileV2__sectionHead"><h3 class="profileV2__sectionTitle">Azioni rapide</h3></div>' +
        '<div class="profileQuick__grid">' + buttons + '</div>' +
    '</section>';
}
function quickActionIcon(name) {
    var map = { palette: '◐', user: '✎', download: '↓', upload: '↑', play: '▶', trash: '🗑', settings: '⚙', info: 'i', bell: '◔' };
    return map[name] || '•';
}
function profileSessionCardHtml() {
    if (!S.active) return '';
    var s = S.active;
    var label = sessionLabel(s);
    var badge = sessionStatusBadgeHtml(s, { size: 'sm' });
    var summary = sessionSummaryLine(s);
    var continueBtn = '<button type="button" class="profileSessionCard__cta" data-action="session-continue" aria-label="Continua la sessione">' + esc(sessionIsActive(s) ? 'Continua' : 'Riprendi') + '</button>';
    var openSheetBtn = '<button type="button" class="profileSessionCard__menu" data-action="session-open" aria-label="Apri opzioni sessione" title="Opzioni">⋮</button>';
    return '<section class="profileV2__section profileV2__session" role="region" aria-labelledby="profileSessionTitle">' +
        '<div class="profileV2__sectionHead"><h3 class="profileV2__sectionTitle" id="profileSessionTitle">Sessione in corso</h3>' + openSheetBtn + '</div>' +
        '<div class="profileSessionCard">' +
            '<div class="profileSessionCard__body">' +
                '<div class="profileSessionCard__label">' + esc(label) + '</div>' +
                '<div class="profileSessionCard__meta">' + badge + '<span class="profileSessionCard__summary">' + esc(summary) + '</span></div>' +
            '</div>' +
            '<div class="profileSessionCard__actions">' + continueBtn + '</div>' +
        '</div>' +
    '</section>';
}
function profileStatsHtml() {
    var UI = window.UI;
    if (!UI || !UI.StatisticCard) return '';
    var workouts = completedSessions().length;
    var sets = profileTotalSets();
    var volume = profileTotalVolume();
    var prs = profilePRCount();
    if (!workouts && !sets && !volume && !prs) return '';
    var grid =
        UI.StatisticCard({ eyebrow: 'Workout completati', value: fmtNum(workouts), unit: '', delta: '' }) +
        UI.StatisticCard({ eyebrow: 'Serie completate',   value: fmtNum(sets),     unit: '', delta: '' }) +
        UI.StatisticCard({ eyebrow: 'Volume totale',      value: fmtNum(volume),   unit: weightUnitLabel(), delta: '' }) +
        UI.StatisticCard({ eyebrow: 'Record personali',   value: fmtNum(prs),      unit: '', delta: '' });
    return '<section class="profileV2__section profileV2__stats" role="region" aria-label="Statistiche personali">' +
        '<div class="profileV2__sectionHead"><h3 class="profileV2__sectionTitle">Statistiche personali</h3></div>' +
        '<div class="profileStats__grid">' + grid + '</div>' +
    '</section>';
}
function prefControlHtml(def) {
    var value = getPref(def.key);
    var badge = def.wired ? '' : '<span class="prefRow__badge">In arrivo</span>';
    var control = '';
    if (def.type === 'switch') {
        var on = !!value;
        control = '<button type="button" class="c-switch prefRow__switch ' + (on ? 'is-on' : '') + '" role="switch" aria-checked="' + (on ? 'true' : 'false') + '" aria-label="' + esc(def.label) + '" data-action="profile-toggle-pref" data-pref="' + esc(def.key) + '"><span class="c-switch__thumb"></span></button>';
    } else if (def.type === 'segmented') {
        control = '<div class="prefRow__segmented" role="group" aria-label="' + esc(def.label) + '">';
        for (var i = 0; i < def.options.length; i++) {
            var opt = def.options[i];
            var active = String(value) === String(opt.value);
            control += '<button type="button" class="prefRow__seg ' + (active ? 'is-active' : '') + '" data-action="profile-set-pref" data-pref="' + esc(def.key) + '" data-value="' + esc(opt.value) + '" aria-pressed="' + (active ? 'true' : 'false') + '">' + esc(opt.label) + '</button>';
        }
        control += '</div>';
    } else if (def.type === 'chips') {
        control = '<div class="prefRow__chips" role="group" aria-label="' + esc(def.label) + '">';
        for (var j = 0; j < def.options.length; j++) {
            var v = def.options[j];
            var isActive = Number(value) === Number(v);
            control += '<button type="button" class="prefRow__chip ' + (isActive ? 'is-active' : '') + '" data-action="profile-set-pref" data-pref="' + esc(def.key) + '" data-value="' + esc(v) + '" aria-pressed="' + (isActive ? 'true' : 'false') + '">' + esc(v + 's') + '</button>';
        }
        control += '</div>';
    }
    return '<div class="prefRow ' + (def.wired ? 'is-wired' : 'is-pending') + '">' +
        '<div class="prefRow__body">' +
            '<div class="prefRow__label">' + esc(def.label) + ' ' + badge + '</div>' +
            (def.meta ? '<div class="prefRow__meta">' + esc(def.meta) + '</div>' : '') +
        '</div>' +
        '<div class="prefRow__control">' + control + '</div>' +
    '</div>';
}
function themeControlHtml() {
    var current = S.theme || 'system';
    var opts = [
        { v: 'system', l: 'Sistema' },
        { v: 'light',  l: 'Chiaro'  },
        { v: 'dark',   l: 'Scuro'   },
        { v: 'amoled', l: 'AMOLED'  }
    ];
    var buttons = opts.map(function (o) {
        var active = current === o.v;
        return '<button type="button" class="prefRow__seg ' + (active ? 'is-active' : '') + '" data-action="profile-set-theme" data-theme="' + esc(o.v) + '" aria-pressed="' + (active ? 'true' : 'false') + '">' + esc(o.l) + '</button>';
    }).join('');
    return '<div class="prefRow is-wired">' +
        '<div class="prefRow__body">' +
            '<div class="prefRow__label">Tema</div>' +
            '<div class="prefRow__meta">Anteprima immediata, nessun riavvio necessario.</div>' +
        '</div>' +
        '<div class="prefRow__control"><div class="prefRow__segmented" role="group" aria-label="Tema">' + buttons + '</div></div>' +
    '</div>';
}
function profilePreferencesHtml() {
    var groups = { 'Aspetto': [], 'Workout': [], 'Accessibilita': [] };
    groups['Aspetto'].push(themeControlHtml());
    for (var i = 0; i < PREF_DEFS.length; i++) {
        var d = PREF_DEFS[i];
        groups[d.group].push(prefControlHtml(d));
    }
    var order = [ ['Aspetto', 'Aspetto'], ['Workout', 'Workout'], ['Accessibilita', 'Accessibilità'] ];
    var html = '';
    for (var g = 0; g < order.length; g++) {
        var key = order[g][0];
        var label = order[g][1];
        var rows = groups[key];
        if (!rows || !rows.length) continue;
        html += '<div class="prefGroup">' +
            '<div class="prefGroup__title">' + esc(label) + '</div>' +
            '<div class="prefGroup__rows">' + rows.join('') + '</div>' +
        '</div>';
    }
    return '<section class="profileV2__section profileV2__prefs" role="region" aria-label="Preferenze">' +
        '<div class="profileV2__sectionHead"><h3 class="profileV2__sectionTitle">Preferenze</h3></div>' +
        html +
    '</section>';
}
function profileDataOpsHtml() {
    var UI = window.UI;
    if (!UI) return '';
    var cfg = (S.sync && S.sync.config) || {};
    var status = (S.sync && S.sync.status) || 'idle';
    var last = S.sync && S.sync.lastSyncAt ? new Date(S.sync.lastSyncAt).toLocaleString() : 'mai';
    var err = S.sync && S.sync.lastError ? ' · Errore: ' + S.sync.lastError : '';
    var online = navigator.onLine ? 'online' : 'offline';
    var syncConfigured = !!(cfg && cfg.token && cfg.owner && cfg.repo);
    var syncBadge = syncConfigured
        ? (status === 'ok'
            ? '<span class="pill pillDone">' + esc(status) + '</span>'
            : '<span class="pill">' + esc(status) + '</span>')
        : '<span class="pill">non configurato</span>';
    var configForm = '<details class="profileDetails" ' + (syncConfigured ? '' : 'open') + '><summary>Configurazione GitHub</summary>' +
        '<div class="stack" style="margin-top:10px">' +
        '<div><label class="meta">Owner (username GitHub)</label><input id="ghOwner" value="' + esc(cfg.owner || '') + '" placeholder="tuo-username" autocapitalize="off" autocorrect="off" spellcheck="false"></div>' +
        '<div><label class="meta">Repo privato</label><input id="ghRepo" value="' + esc(cfg.repo || '') + '" placeholder="fit-tracker-data" autocapitalize="off" autocorrect="off" spellcheck="false"></div>' +
        '<div><label class="meta">File</label><input id="ghPath" value="' + esc(cfg.path || 'backup.json') + '" placeholder="backup.json" autocapitalize="off" autocorrect="off" spellcheck="false"></div>' +
        '<div><label class="meta">Branch</label><input id="ghBranch" value="' + esc(cfg.branch || 'main') + '" placeholder="main" autocapitalize="off" autocorrect="off" spellcheck="false"></div>' +
        '<div><label class="meta">Personal Access Token</label><input id="ghToken" type="password" value="' + esc(cfg.token || '') + '" placeholder="github_pat_..." autocapitalize="off" autocorrect="off" spellcheck="false"></div>' +
        '</div>' +
        '<div class="row" style="margin-top:10px">' +
        UI.Button({ label: 'Salva',    variant: 'primary', dataset: { action: 'save-sync-config' } }) +
        UI.Button({ label: 'Rimuovi',  variant: 'danger',  dataset: { action: 'clear-sync-config' } }) +
        '</div>' +
        '</details>';
    var syncCard =
        '<div class="profileDataOps__card">' +
            '<div class="profileDataOps__head"><h4>GitHub sync</h4>' + syncBadge + '</div>' +
            '<p class="profileDataOps__meta">Sync automatico su repo privato. Se offline, il salvataggio parte alla prima connessione.</p>' +
            configForm +
            '<div class="row" style="margin-top:10px">' +
            UI.Button({ label: 'Sync ora',   variant: 'secondary', dataset: { action: 'sync-now' } }) +
            UI.Button({ label: 'Ripristina', variant: 'secondary', dataset: { action: 'restore-remote' } }) +
            '</div>' +
            '<p class="profileDataOps__status" id="syncStatus" aria-live="polite">Stato: ' + esc(status) + ' · ' + online + ' · Ultimo sync: ' + esc(last) + esc(err) + '</p>' +
        '</div>';
    var localOps =
        '<div class="profileDataOps__card">' +
            '<div class="profileDataOps__head"><h4>Backup locale</h4></div>' +
            '<p class="profileDataOps__meta">Salva o carica un backup completo (schede, esercizi, sessioni).</p>' +
            '<div class="row">' +
            UI.Button({ label: 'Esporta JSON', variant: 'secondary', dataset: { action: 'export-all' } }) +
            UI.Button({ label: 'Importa JSON', variant: 'secondary', dataset: { action: 'import-json' } }) +
            '</div>' +
        '</div>';
    var danger =
        '<div class="profileDataOps__card profileDataOps__card--danger">' +
            '<div class="profileDataOps__head"><h4>Zona pericolosa</h4></div>' +
            '<p class="profileDataOps__meta">Reset scheda: reimposta la scheda con quella embedded (non tocca sessioni ed esercizi già registrati). Ripristina impostazioni: torna ai valori di default per tema, animazioni e preferenze.</p>' +
            '<div class="row">' +
            UI.Button({ label: 'Ripristina impostazioni', variant: 'ghost',  dataset: { action: 'profile-reset-prefs' } }) +
            UI.Button({ label: 'Reset scheda',            variant: 'danger', dataset: { action: 'confirm-reset' } }) +
            '</div>' +
        '</div>';
    return '<section class="profileV2__section profileV2__data" role="region" aria-label="Gestione dati">' +
        '<div class="profileV2__sectionHead"><h3 class="profileV2__sectionTitle">Gestione dati</h3></div>' +
        syncCard + localOps + danger +
    '</section>';
}
